def parse_records(text):
 out=[]
 for line in text.splitlines():
  if not line.strip(): continue
  parts=line.split(':',1)
  if len(parts)!=2: raise ValueError('malformed record: %r'%line)
  key,value=parts;out.append((key.strip(),value.strip()))
 return out
